(function(){
  'use strict';
  const M=window.LouxiangModel,P=window.LouxiangProjects,U=window.HSUI,V=window.LouxiangViews,L=window.LouxiangAssistant,S=window.LouxiangAssistantSessions,W=window.LouxiangAssistantView;
  const E=U.escape,I=U.icon,B=U.badge,A=U.avatar;
  const storageKey='housignal-demo-projects-v1';
  const titles={assistant:'楼管家',dashboard:'工作台',studio:'内容工作室',property:'楼盘资料',assets:'素材库',leads:'咨询与客户',reports:'效果分析',settings:'组织设置'};
  const steps=[['topics','选题策划'],['script','文案与分镜'],['visual','视觉制作'],['review','发布审核'],['publish','发布与回执'],['learn','复盘优化']];
  const stages={qualified:'需求已确认',appointment:'已预约',visit_completed:'已完成带看',opportunity:'方案沟通',won:'已成交',lost:'已结束',withdrawn:'已退出'};
  const sourceLabels={confirmed:'已确认来源',self_reported:'客户自述',inferred:'关联待核',unknown:'来源未知'};
  let restored=null;
  try{restored=JSON.parse(localStorage.getItem(storageKey)||'null');if(!restored)restored=JSON.parse(localStorage.getItem('housignal-demo-v2')||'null');}catch(_){}
  let workspace=P.createWorkspace(restored);
  let state=P.getActiveProject(workspace).state;
  const ui={page:'dashboard',workspaceTab:'overview',step:'topics',factFilter:'all',assetFilter:'all',leadView:'table',reportWindow:'D7',role:'content',search:'',allTopics:false,channel:state.campaign.channel,mobile:false,previewPlaying:false,previewTime:0,audience:state.property.audience||''};
  const chatStorageKey='housignal-demo-agent-v1';
  let restoredChat=null;
  try{restoredChat=JSON.parse(localStorage.getItem(chatStorageKey)||'null');}catch(_){}
  let chats=S.createSession(restoredChat),chatEpoch=0;
  function saveChats(){try{localStorage.setItem(chatStorageKey,JSON.stringify(chats));}catch(_){}}
  saveChats();
  let toastTimer,previewTimer,lastFocused;
  function normalizeAssets(){state=P.getActiveProject(workspace).state;state.assets.forEach(a=>{if(window.HSAssets&&window.HSAssets[a.src])a.src=window.HSAssets[a.src];});}
  function save(){try{const compact=JSON.parse(JSON.stringify(workspace,(key,value)=>{if((key==='src'||key==='heroSrc')&&typeof value==='string'&&value.startsWith('data:')&&window.HSAssets){return Object.keys(window.HSAssets).find(path=>window.HSAssets[path]===value)||value;}return value;}));localStorage.setItem(storageKey,JSON.stringify(P.sanitizeForStorage(compact)));}catch(_){}}
  normalizeAssets();
  function toast(text,error=false){clearTimeout(toastTimer);document.getElementById('toast-root').innerHTML='<div class="toast '+(error?'error':'')+'">'+I(error?'info':'check',15)+'<span>'+E(text)+'</span></div>';toastTimer=setTimeout(()=>{document.getElementById('toast-root').innerHTML='';},3800);}
  function act(action,options={}){
    const projectId=options.projectId||workspace.activeProjectId;
    const result=P.dispatch(workspace,projectId,action);
    if(result.error){if(options.errorTarget&&document.getElementById(options.errorTarget)){document.getElementById(options.errorTarget).innerHTML='<div class="modal-error">'+E(result.error)+'</div>';}else toast(result.error,true);return false;}
    workspace=result.workspace;normalizeAssets();save();
    if(options.render!==false)render();
    if(options.toast!==false&&result.message){const target=P.getProject(workspace,projectId);toast((projectId!==workspace.activeProjectId?target.state.property.name+'：':'')+result.message);}
    return true;
  }
  function goto(page,step){stopPreview();if(page==='reports'){ui.workspaceTab='effects';page='dashboard';}else if(page==='dashboard'){ui.workspaceTab='overview';}ui.page=page;ui.mobile=false;if(step)ui.step=step;closeModal();render();window.scrollTo({top:0,behavior:'instant'});}
  function renderedState(){return {...state,...ui,leadSearch:ui.search,heroSrc:hero(),teamName:workspace.team.name,projectCompleteness:P.getCompleteness(state)};}
  function selectedTopic(){return state.topics.find(x=>x.id===state.campaign.topicId)||state.topics[0]||{title:'从一个生活问题开始',refs:[],audience:'待补充目标需求',angle:'先完善当前项目资料'};}
  function asset(path){return (window.HSAssets&&window.HSAssets[path])||path;}
  function photo(n=1){const valid=state.assets.filter(a=>a.src);return valid.length?asset(valid[(n-1)%valid.length].src):placeholder();}
  function hero(){return state.property.heroSrc?asset(state.property.heroSrc):null;}
  function placeholder(){return 'data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="480" height="320"><rect width="480" height="320" fill="#eef2f7"/><path d="M170 220V110l70-35 70 35v110M150 220h180M215 220v-65h50v65" fill="none" stroke="#c1ccdc" stroke-width="3"/></svg>');}
  function brandMark(){return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none"><path d="M5 19V6h5v13M14 19V3h5v16M3 19h18" stroke="white" stroke-width="1.5" stroke-linecap="round"/><path d="M7.5 9h0m0 3h0m9-5h0m0 4h0m0 4h0" stroke="white" stroke-width="2" stroke-linecap="round"/></svg>';}
  function sidebar(){
    const entries=[['dashboard','grid','工作台'],['studio','studio','内容工作室'],['property','building','楼盘资料'],['assets','image','素材库'],['leads','users','咨询与客户']];
    const pending=state.inquiries.filter(x=>!x.qualified).length,completeness=P.getCompleteness(state);
    return '<aside class="sidebar '+(ui.mobile?'mobile-open':'')+'"><a class="brand" href="#" data-action="navigate" data-page="dashboard"><span class="brand-mark">'+brandMark()+'</span><div><div class="brand-name">楼响</div><div class="brand-sub">HOUSIGNAL</div></div></a><div class="project-selector"><span class="project-selector-label">当前项目</span><button class="project-trigger" data-action="project-selector" aria-label="当前项目：'+E(state.property.name)+'，打开项目选择器"><span class="project-trigger-icon">'+I('building',16)+'</span><span class="project-trigger-copy"><strong>'+E(state.property.name)+'</strong><small>'+E(state.property.city||'待填写城市')+' · 资料 '+completeness.percent+'%</small></span>'+I('chevron',13)+'</button></div><button class="sidebar-search" data-action="command">'+I('search',15)+'<span>搜索工作区</span><kbd>⌘ K</kbd></button><nav class="butler-entry" aria-label="楼管家"><button class="nav-item '+(ui.page==='assistant'?'active':'')+'" data-action="navigate" data-page="assistant" '+(ui.page==='assistant'?'aria-current="page"':'')+'>'+I('sparkle',17)+'<span>楼管家</span></button></nav><div class="nav-label">WORKSPACE</div><nav class="nav-list" aria-label="主导航">'+entries.map(([page,icon,name])=>'<button class="nav-item '+(ui.page===page?'active':'')+'" data-action="navigate" data-page="'+page+'" '+(ui.page===page?'aria-current="page"':'')+'>'+I(icon,17)+'<span>'+name+'</span>'+((page==='assets'||page==='leads')?'<span class="nav-count">'+(page==='assets'?state.assets.length:pending)+'</span>':'')+'</button>').join('')+'</nav><div class="sidebar-bottom"><button class="project-progress-shortcut" data-action="project-completeness"><span>'+I('shield',14)+' 项目资料完整度</span><strong>'+completeness.completed+'/'+completeness.total+I('arrow-right',12)+'</strong></button><div class="account-row"><span class="avatar dark">林</span><div><div class="account-name">林嘉宁</div><div class="account-role">'+({content:'内容负责人',sales:'销售顾问',reviewer:'审核负责人'}[ui.role])+'</div></div><button class="icon-btn" data-action="navigate" data-page="settings" aria-label="组织设置">'+I('settings',16)+'</button></div></div></aside>';
  }
  function topbar(){return '<header class="topbar"><div class="breadcrumbs"><button class="icon-btn mobile-menu" data-action="mobile-menu" aria-label="打开导航">'+I('menu')+'</button><button class="crumb-project" data-action="project-selector" aria-label="切换当前项目">'+E(state.property.name)+I('chevron',11)+'</button><span class="slash">/</span><span class="crumb-current">'+titles[ui.page]+'</span>'+((ui.page==='dashboard')?'<span class="slash">/</span><span class="crumb-current">'+(ui.workspaceTab==='effects'?'效果分析':'项目总览')+'</span>':'')+'</div><div class="topbar-right"><span class="demo-indicator"><span class="demo-dot"></span>交互演示 · 示例数据</span><button class="btn ghost small" data-action="tour">'+I('play',12)+'快速导览</button><button class="icon-btn notification" data-action="notifications" aria-label="查看待办通知">'+I('bell',17)+'</button><button class="icon-btn" data-action="role-menu" aria-label="切换演示角色"><span class="avatar mini">林</span></button></div></header>';}
  function pageHeader(eyebrow,title,subtitle,actions=''){return '<div class="page-heading"><div><div class="eyebrow">'+eyebrow+'</div><h1>'+title+'</h1><p>'+subtitle+'</p></div><div class="heading-actions">'+actions+'</div></div>';}
  function sparkline(values,color='#a8bbdf'){const points=values.map((v,i)=>(i*9)+','+(24-v)).join(' ');return '<svg class="stat-sparkline" viewBox="0 0 65 24" fill="none" aria-hidden="true"><polyline points="'+points+'" stroke="'+color+'" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
  function dashboard(){
    const complete=P.getCompleteness(state);
    const header=pageHeader('PROJECT WORKSPACE','工作台','掌握项目进展、内容效果与下一步安排。','<button class="btn" data-action="project-completeness">'+I('shield',14)+'资料 '+complete.completed+'/'+complete.total+'</button><button class="btn primary" data-action="new-content">'+I('plus',15)+'开始创作</button>');
    const tabs='<nav class="workbench-tabs" aria-label="工作台视图">'+[['overview','项目总览'],['effects','效果分析']].map(([value,label])=>'<button class="workbench-tab '+(ui.workspaceTab===value?'active':'')+'" data-action="workspace-tab" data-value="'+value+'" aria-pressed="'+(ui.workspaceTab===value)+'">'+I(value==='overview'?'grid':'chart',15)+label+'</button>').join('')+'</nav>';
    return header+tabs+(ui.workspaceTab==='effects'?V.reports({...renderedState(),embedded:true}):dashboardOverview());
  }
  function dashboardOverview(){
    const metrics=M.getMetrics(state),topic=selectedTopic(),c=state.campaign,p=state.property,complete=P.getCompleteness(state);
    const required=state.facts.filter(f=>f.required),ready=required.filter(f=>f.status==='verified').length;
    const current=c.release&&c.release.valid?'审核完成':c.renderedVersion===c.scriptVersion&&c.scriptVersion?'待发布审核':c.script?'文案已就绪':ready===required.length&&required.length?'选题待确认':'资料待完善';
    const stats=[['公开作品',metrics.published,'回执确认 + 公开展示','studio'],['主动咨询',metrics.inquiries,'其中 '+state.inquiries.filter(q=>!q.qualified).length+' 条待销售确认','message'],['资格客户',metrics.qualified,'由销售人工确认需求','users'],['已完成带看',metrics.visits,'预约与实际带看分开','calendar']];
    const area=state.facts.find(f=>f.id==='F01'),layout=state.facts.find(f=>f.id==='F03');
    const facts=[area&&area.status==='verified'?E(area.value)+' '+E(area.unit)+' '+E(area.label):'面积待核验',layout&&layout.status==='verified'?E(layout.value):'房型待核验',E(p.audience||'目标需求待补充')];
    const pending=state.inquiries.find(q=>!q.qualified),price=state.facts.find(f=>f.id==='F05');
    const firstAction=pending?'open-inquiry':'project-completeness';
    return '<div class="overview-grid"><section class="property-feature '+(!hero()?'property-feature-empty':'')+'">'+(hero()?'<img src="'+E(hero())+'" alt="当前项目视觉示意">':'<div class="project-empty-art">'+I('building',56)+'<span>等待补充本项目资料与素材</span></div>')+'<div class="feature-top"><span class="eyebrow">PROPERTY IN FOCUS</span>'+B(p.visualLabel||'项目资料待补充',hero()?'transparent':'gray')+'</div><div class="hero-caption"><h2>'+E(p.name)+'</h2><p>'+E(p.subtitle||[p.city,p.propertyType].filter(Boolean).join(' · '))+'</p><div class="feature-facts">'+facts.map(f=>'<span>'+f+'</span>').join('')+'</div><button class="feature-open" data-action="navigate" data-page="property" aria-label="查看楼盘资料">'+I('arrow-right',17)+'</button></div></section>'+
      '<section class="card focus-card"><div class="focus-card-top"><span class="eyebrow">CONTINUE CREATING</span>'+B(current,'blue')+'</div><h2>'+E(topic.title)+'</h2><p>'+((ready===required.length&&required.length)?'把空间事实，翻译成客户能理解的生活。':'先完善当前项目资料，再生成有依据的内容。')+'</p><div class="focus-meta">'+B(p.audience||'目标需求待补充','gray')+B('60–90 秒','gray')+B(c.channel==='小红书'?'小红书适配':'抖音主版','gray')+'</div><div class="micro-progress">'+steps.map((x,i)=>'<span class="'+(ready&&i===0?'done':i===1?'current':'')+'"></span>').join('')+'</div><div class="focus-footer"><span class="focus-owner">'+A(p.owner||'待')+' '+ready+' 项核心事实已就绪</span><button class="btn primary small" data-action="continue-content">'+(c.script?'继续创作':'进入工作室')+I('arrow-right',13)+'</button></div></section></div>'+
      '<div class="stat-grid">'+stats.map(([label,value,note,icon])=>'<div class="stat-card"><div class="stat-label">'+label+I(icon,14)+'</div><div class="row" style="justify-content:space-between"><div class="stat-value">'+value+'</div>'+(value?sparkline([4,4,8,7,13,11,16,19]):'')+'</div><div class="stat-note">'+note+'</div></div>').join('')+'</div>'+
      '<div class="grid-2 workbench-summary-grid">'+V.effectSummary(renderedState())+V.reviewSummary(renderedState())+'</div>'+
      '<div class="lower-grid"><section class="card content-table"><div class="card-header"><h3>内容进展</h3><button class="btn text" data-action="navigate" data-page="studio">打开工作室'+I('arrow-right',13)+'</button></div>'+(state.publications.length?'<div class="table-wrap"><table class="data-table"><thead><tr><th>内容</th><th>状态</th><th>渠道</th><th>D7 播放</th><th></th></tr></thead><tbody>'+state.publications.slice(-3).map((publication,i)=>'<tr data-action="show-publication" data-id="'+E(publication.id)+'" tabindex="0" role="button"><td><div class="row"><div class="content-thumb"><img src="'+E(photo(i+1))+'" alt="本项目内容封面示意"></div><div><div class="content-name">'+E(publication.title)+'</div><div class="content-sub">'+E(publication.at)+' · '+E(p.name)+'</div></div></div></td><td>'+B(publication.status==='verified'&&publication.platformState==='live'?'已公开':'回执待确认',publication.status==='verified'?'green':'amber')+'</td><td>'+E(publication.channel)+'</td><td>'+((publication.views==null)?'<span class="faint">待回填</span>':Number(publication.views).toLocaleString('zh-CN'))+'</td><td>'+I('arrow-right',14)+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty-state">'+I('studio',28)+'<h3>这个项目还没有发布记录</h3><p>资料、内容和审批都在本项目内独立保存。</p><button class="btn small" data-action="new-content">开始第一条内容</button></div>')+'</section>'+
      '<section class="card"><div class="card-header"><h3>今天，推进这几件事</h3>'+B('本项目提醒','gray')+'</div><div class="card-body" style="padding-top:4px;padding-bottom:5px"><div class="task-item" data-action="'+firstAction+'" '+(pending?'data-id="'+E(pending.id)+'"':'')+' tabindex="0" role="button"><span class="task-icon">'+I(pending?'users':'shield',16)+'</span><div><div class="task-title">'+(pending?'接住一条新咨询':'查看项目资料准备情况')+'</div><div class="task-description">'+(pending?'需求与联系同意，等待销售确认':'已完成 '+complete.completed+' / '+complete.total+' 项准备')+'</div></div>'+I('arrow-right',13)+'</div>'+(price?'<div class="task-item" data-action="show-fact" data-id="'+E(price.id)+'" tabindex="0" role="button"><span class="task-icon">'+I('file',16)+'</span><div><div class="task-title">'+(price.status==='verified'?'核对具体房源报价':'补齐具体房源报价依据')+'</div><div class="task-description">报价按本项目依据单独核验</div></div>'+I('arrow-right',13)+'</div>':'')+'<div class="task-item" data-action="navigate" data-page="reports" tabindex="0" role="button"><span class="task-icon">'+I('chart',16)+'</span><div><div class="task-title">把销售问题带回下一轮选题</div><div class="task-description">'+state.proposals.filter(proposal=>proposal.status==='pending').length+' 条本项目建议待采纳</div></div>'+I('arrow-right',13)+'</div></div></section></div>';
  }
  function workflowNav(){const index=steps.findIndex(x=>x[0]===ui.step);return '<nav class="workflow-steps" aria-label="内容流程">'+steps.map(([value,label],i)=>'<button class="workflow-step '+(i===index?'active':i<index?'done':'')+'" data-action="workflow-step" data-value="'+value+'" '+(i===index?'aria-current="step"':'')+'><span class="step-num">'+(i<index?I('check',12):(i+1))+'</span>'+label+'</button>').join('')+'</nav>';}
  function studio(){const c=state.campaign;return pageHeader('CONTENT STUDIO','内容工作室','一次专业讲解，连接一个真实的生活问题。','<button class="btn ghost" data-action="navigate" data-page="property">'+I('shield',14)+'查看事实簿</button>'+B(c.scriptVersion?'草稿 v'+c.scriptVersion:'新内容','gray'))+workflowNav()+({topics:topicView,script:scriptView,visual:visualView,review:reviewView,publish:publishView,learn:learnView}[ui.step]||topicView)();}
  function briefCard(){const verified=state.facts.filter(f=>f.required&&f.status==='verified').length;return '<aside class="card brief-card"><div class="card-header"><h3>本次创作简报</h3>'+I('target',16)+'</div><div class="card-body"><label for="brief-audience">目标生活需求</label><select id="brief-audience">'+(state.property.audience&&!['家庭改善与日常共处','长辈同住与日常动线','会客空间与家庭生活'].includes(state.property.audience)?'<option>'+E(state.property.audience)+'</option>':'')+'<option>家庭改善与日常共处</option><option>长辈同住与日常动线</option><option>会客空间与家庭生活</option></select><label for="brief-channel">主发布渠道</label><select id="brief-channel"><option>抖音 · 口播短视频</option><option>小红书 · 图文适配</option></select><label>核心资料</label><div class="row">'+B(verified+' 项已核验','green')+B(state.assets.filter(a=>a.rights==='authorized').length+' 个素材可用','gray')+'</div><div class="brief-summary">用具体空间回答生活问题。<br>有依据的事实、可解释的取舍、一次可以兑现的咨询邀请。</div><div style="margin-top:19px;font-size:9px;color:#a2adbd">表达方向 · 专业顾问 / 生活体验<br>销售承接 · 平台内人工咨询</div></div></aside>';}
  function topicView(){const preferred=ui.audience==='长辈同住与日常动线'?['T02','T05','T04','T01','T03']:ui.audience==='会客空间与家庭生活'?['T01','T03','T05','T02','T04']:['T01','T02','T03','T04','T05'];const ranked=preferred.map(id=>state.topics.find(t=>t.id===id));const topics=ui.allTopics?ranked:ranked.slice(0,3);return '<div class="studio-layout"><div><div class="section-title"><div><h2>从一个好问题开始</h2><p>根据现有事实、空间素材和销售常见问题策划。</p></div><button class="btn small" data-action="refresh-topics">'+I('sparkle',13)+'整理选题</button></div><div class="stack">'+topics.map(t=>'<article class="topic-card '+(state.campaign.topicId===t.id?'selected':'')+'" data-action="select-topic" data-id="'+t.id+'" role="button" tabindex="0" aria-pressed="'+(state.campaign.topicId===t.id)+'"><div class="topic-top"><span class="topic-radio"></span><h3>'+E(t.title)+'</h3><span class="spacer"></span>'+B(t.tag,'gray')+'</div><div class="topic-details"><p>'+E(t.angle)+'</p><div class="topic-bottom"><span>'+I('user',12)+' '+E(t.audience)+'</span><span>'+I('shield',12)+' '+t.refs.length+' 项依据</span></div></div></article>').join('')+'</div><button class="btn ghost" data-action="all-topics" style="margin-top:13px;font-size:10px;width:100%">'+(ui.allTopics?'收起更多选题':'查看另外 2 个选题')+I('chevron',12)+'</button></div>'+briefCard()+'</div><div class="studio-footer"><span class="muted">'+(state.campaign.topicId?'已选择 1 个主选题':'选择一个问题，开始本轮内容')+'</span><button class="btn primary" data-action="generate-script">'+I('sparkle',14)+'生成文案草稿'+I('arrow-right',14)+'</button></div>';}
  function scriptView(){const c=state.campaign;if(!c.script)return '<div class="card empty-state">'+I('file',30)+'<h3>先选定本次内容的问题</h3><p>从事实与真实空间出发，生成一版可编辑的口播稿。</p><button class="btn primary" data-action="workflow-step" data-value="topics" style="margin-top:20px">返回选题'+I('arrow-left',13)+'</button></div>';const facts=state.facts.filter(f=>c.factRefs.includes(f.id));return '<div class="studio-layout"><section class="card"><div class="card-header"><h3>口播脚本</h3><div class="row">'+B('v'+c.scriptVersion,'gray')+'<button class="btn ghost small" data-action="copy-script">'+I('copy',13)+'复制</button></div></div><div class="card-body"><div class="script-sections"><span>提出问题</span><span>空间证据</span><span>生活解释</span><span>适配取舍</span><span>咨询邀请</span></div><textarea id="script-editor" class="script-editor" aria-label="编辑口播脚本" spellcheck="false">'+E(c.script)+'</textarea><div class="row" style="justify-content:space-between;font-size:9px;color:#a3acba;padding-top:12px;border-top:1px solid #eef0f4"><span>约 75 秒 · 时长为分镜目标</span><span>人工编辑后保存为新版本</span></div></div></section><aside class="stack"><section class="card"><div class="card-header"><h3>每一句，都有依据</h3>'+B(facts.length+' 项引用','green')+'</div><div class="card-body" style="padding-top:4px;padding-bottom:7px">'+facts.map(f=>'<div class="evidence-item" data-action="show-fact" data-id="'+f.id+'" role="button" tabindex="0" style="cursor:pointer"><span class="evidence-check">'+I(f.status==='verified'?'check':'info',11)+'</span><div><strong>'+E(f.label)+' · '+E(f.value)+' '+E(f.unit)+'</strong><p>'+E(f.source)+'</p><span class="evidence-ref">'+E(f.id)+' · '+(f.status==='verified'?'资料负责人已核验':'需重新核验')+'</span></div></div>').join('')+'</div></section><div class="note-box">'+I('info',14)+'<span>生活意义属于顾问判断，事实与感受分别表达。尚未核验的报价不会进入这份草稿。</span></div><section class="card"><div class="card-body"><h3 style="font-size:11px;color:#75859a">让表达保留专业判断</h3><p class="muted" style="font-size:10px;line-height:1.9;margin-top:9px">可以讲清适合的人，也可以说明需要权衡的条件。每一条内容，只回答一个问题。</p></div></section></aside></div><div class="studio-footer"><button class="btn ghost" data-action="workflow-step" data-value="topics">'+I('arrow-left',14)+'返回选题</button><div class="row"><button class="btn" data-action="save-script">保存修改</button><button class="btn primary" data-action="to-visual">下一步 · 视觉制作'+I('arrow-right',14)+'</button></div></div>';}
  function phonePreview(){const topic=selectedTopic(),cover=state.campaign.coverTitle||topic.title,images=[3,1,2];const idx=Math.min(2,Math.floor(ui.previewTime/25));return '<div class="media-stage"><div class="phone-preview '+(state.campaign.aspectRatio==='16:9'?'wide':'')+'"><img id="scene-photo" class="scene-photo '+(ui.previewPlaying?'playing':'')+'" src="'+photo(images[idx])+'" alt="空间照片组成的演示分镜"><div class="phone-overlay-top">HOUSIGNAL / 空间示意</div><div class="phone-title">'+E(cover.replace('，','，<br>')).replace('&lt;br&gt;','<br>')+'</div><div id="preview-subtitle" class="phone-subtitle '+(state.campaign.subtitleStyle==='emphasis'?'emphasis':'')+'">'+(idx===0?'家的尺度，从生活开始。':idx===1?'把空间的细节，讲给对的人。':'适合与否，让真实需求来回答。')+'</div><button class="play-overlay" data-action="preview-play" aria-label="'+(ui.previewPlaying?'暂停分镜预览':'播放分镜预览')+'">'+I(ui.previewPlaying?'pause':'play',19)+'</button></div><span class="media-stage-note">照片序列示意 · 非已渲染成片</span></div><div class="media-controls"><button class="icon-btn" data-action="preview-play" aria-label="播放或暂停">'+I(ui.previewPlaying?'pause':'play',14)+'</button><span id="preview-time">00:'+String(ui.previewTime).padStart(2,'0')+'</span><input type="range" id="preview-range" min="0" max="75" value="'+ui.previewTime+'" aria-label="分镜预览进度"><span>01:15</span></div>';}
  function visualView(){const ready=state.campaign.renderedVersion===state.campaign.scriptVersion&&state.campaign.scriptVersion>0;const shots=[['00–08','开场 · 一个生活问题','先看生活需求，再理解空间的尺度。',3],['08–32','空间 · 用细节回答','用已核验事实组织具体镜头，不补造房况。',1],['32–50','场景 · 把专业讲明白','从家人相处到日常会客，解释使用条件。',2],['50–75','取舍 · 连接合适的人','保留适配边界，给出一次站内咨询邀请。',3]];return '<div class="media-layout"><section><div class="section-title"><h2>竖版分镜预览</h2>'+B(ready?'预览已就绪':'待生成预览',ready?'green':'gray')+'</div>'+phonePreview()+'</section><div class="stack"><section class="card"><div class="card-header"><h3>镜头与叙事顺序</h3>'+B('4 个分镜','gray')+'</div><div class="card-body" style="padding-top:3px;padding-bottom:3px">'+shots.map(([time,label,copy,n],i)=>'<div class="shot-row"><span class="shot-number">0'+(i+1)+'</span><div class="shot-img"><img src="'+photo(n)+'" alt="摄影示意镜头"><small>'+time+'</small></div><div class="shot-copy"><strong>'+label+'</strong><p>'+copy+'</p><div class="shot-tags">'+B('空间示意','gray')+B(i===1?'事实依据':'编辑建议',i===1?'green':'blue')+'</div></div></div>').join('')+'</div></section><section class="card"><div class="card-body"><div class="media-setting"><span>画面比例</span><select id="ratio-select" aria-label="画面比例"><option value="9:16" '+(state.campaign.aspectRatio!=='16:9'?'selected':'')+'>9:16 · 竖版</option><option value="16:9" '+(state.campaign.aspectRatio==='16:9'?'selected':'')+'>16:9 · 横版</option></select></div><div class="media-setting"><span>字幕表达</span><select id="subtitle-style" aria-label="字幕表达"><option value="standard" '+(state.campaign.subtitleStyle!=='emphasis'?'selected':'')+'>简洁白字 · 两行以内</option><option value="emphasis" '+(state.campaign.subtitleStyle==='emphasis'?'selected':'')+'>重点字幕强调</option></select></div><div class="media-setting"><span>封面标题</span><button class="btn ghost small" data-action="cover-edit">编辑封面文案'+I('edit',12)+'</button></div></div></section></div></div><div class="studio-footer"><button class="btn ghost" data-action="workflow-step" data-value="script">'+I('arrow-left',13)+'返回文案</button><div class="row"><button class="btn" data-action="render-preview">'+I('play',14)+'生成分镜预览</button><button class="btn primary" data-action="to-review">提交审核'+I('arrow-right',14)+'</button></div></div>';}
  function reviewView(){const c=state.campaign,valid=c.release&&c.release.valid;const checks=[['房屋事实','引用资料仍有效，面积与单位口径明确',state.facts.filter(f=>f.required).every(f=>f.status==='verified')],['素材用途','本次演示素材的权利状态已登记',state.assets.every(a=>a.rights==='authorized')],['文案与画面','预览对应当前脚本版本，字幕需人工检查',c.scriptVersion>0&&c.renderedVersion===c.scriptVersion],['平台包装','当前渠道为'+c.channel+'，标题与咨询邀请已列入版本',!!c.script],['咨询入口','平台内人工承接，不预设开放接口权限',true]];if(c.projectNameNeedsReview)checks.unshift(['项目名称','项目已更名，保留旧稿；请重新生成或更新文案中的项目名称',false]);return '<div class="studio-layout equal"><section class="card"><div class="card-header"><h3>审核当前发布版本</h3>'+B('v'+c.scriptVersion,'gray')+'</div><div class="card-body"><div class="review-preview"><img src="'+photo(3)+'" alt="待审核内容的空间示意"><p>'+E(state.campaign.coverTitle||selectedTopic().title)+'</p></div><div class="row" style="justify-content:space-between;font-size:10px;color:#97a4b6"><span>'+E(c.channel)+' · '+E(c.aspectRatio||'9:16')+' 分镜 · 示例审核</span><span>内容负责人 '+E(state.property.owner||'待指定')+'</span></div><div class="note-box">'+I('shield',14)+'<span>批准只对应这一版内容。文案、事实或素材改变后，原批准结论失效。</span></div></div></section><section class="card"><div class="card-header"><h3>逐项确认，放心交付</h3>'+B(valid?'已批准':'待审核',valid?'green':'amber')+'</div><div class="card-body" style="padding-top:3px">'+checks.map(([label,note,pass])=>'<div class="review-item"><span class="'+(pass?'review-ok':'review-pending')+'">'+I(pass?'check':'clock',12)+'</span><div><strong>'+label+'</strong><p>'+note+'</p></div>'+B(pass?'可核对':'待补齐',pass?'green':'amber')+'</div>').join('')+'<div class="input-group" style="margin-top:18px"><label for="review-note">审核备注</label><textarea id="review-note" placeholder="记录核对范围、取舍条件或需要修改的内容。">'+E(c.reviewDecision?.note||'')+'</textarea></div><label class="checkbox-line"><input id="review-confirm" type="checkbox" '+(valid?'checked':'')+'><span>我已核对当前版本的事实、素材、表达与咨询路径。</span></label>'+(valid?'<div class="info-strip" style="margin:16px 0 0">'+I('check',14)+'示例审核已完成 · 修改后需重新审核</div>':'')+'</div></section></div><div class="studio-footer"><button class="btn ghost" data-action="workflow-step" data-value="visual">'+I('arrow-left',13)+'返回制作</button><div class="row">'+(!valid?'<button class="btn primary" data-action="approve-release">'+I('check',14)+'批准当前版本</button>':'<button class="btn primary" data-action="workflow-step" data-value="publish">下一步 · 导出与发布'+I('arrow-right',14)+'</button>')+'</div></div>';}
  function publishView(){const c=state.campaign,valid=c.release&&c.release.valid;const xhs=ui.channel==='小红书';return '<div class="studio-layout equal"><section class="card"><div class="card-header"><h3>渠道发布包</h3><div class="tab-bar"><button class="tab '+(!xhs?'active':'')+'" data-action="publish-channel" data-value="抖音">抖音</button><button class="tab '+(xhs?'active':'')+'" data-action="publish-channel" data-value="小红书">小红书</button></div></div><div class="publish-card"><div class="publish-cover"><img src="'+photo(3)+'" alt="发布封面示意"><p>'+E(state.campaign.coverTitle||selectedTopic().title)+'</p></div><div class="publish-copy">'+B(xhs?'图文适配':'口播主版','blue')+'<h3>'+E(selectedTopic().title)+'</h3><p>'+(xhs?'把空间判断拆成可收藏的图文说明。每张图对应一个真实问题，保留相同事实与限定条件。':'从一个具体居住问题出发，讲清空间事实、生活意义和适合的条件。')+'</p></div></div><div class="card-body" style="padding-top:0"><div class="input-group"><label>内容简介</label><div style="font-size:11px;color:#7b889b;line-height:1.9;border:1px solid #e8edf4;border-radius:7px;padding:13px">'+(xhs?'① 先明确生活需求<br>② 核对空间与面积口径<br>③ 解释日常使用条件<br>④ 保留需要现场验证的事项':'每一套好房，都有自己的使用条件。理解空间，也理解自己想要的生活。')+'<br><br>有类似居住问题，可在平台内主动咨询。</div></div><div class="row" style="justify-content:space-between;margin-top:17px"><span class="muted" style="font-size:9px">示例包：文案 · 分镜清单 · 审核说明</span><button class="btn primary small" data-action="export-release">'+I('download',13)+'导出发布包</button></div><div class="publish-status-strip"><p>'+I('info',13)+' 导出完成后，由运营在平台界面人工发布。</p>'+B(c.exported?'已导出':'待导出',c.exported?'green':'gray')+'</div></div></section><section class="card"><div class="card-header"><h3>登记发布回执</h3>'+B('人工回填','gray')+'</div><div class="card-body">'+(!valid?'<div class="error-banner">当前版本尚无有效审批，请先完成审核。</div>':'')+'<div class="input-group"><label for="publication-url">作品链接或编号</label><input id="publication-url" placeholder="填写完整作品链接，或平台作品编号"><p class="input-help">演示可填写 https://example.com/my-content，不会提交到平台。</p></div><div class="input-group"><label for="publication-platform-state">平台实际状态</label><select id="publication-platform-state"><option value="review_pending">平台审核中</option><option value="live">已公开展示</option></select></div><div class="input-group"><label>回执核对</label><div class="row" style="font-size:11px;color:#91a0b6">'+I('clock',14)+'登记后进入待核对，保留实际平台状态。</div></div><div id="publication-error"></div><button class="btn" data-action="record-publication" style="width:100%;margin-top:5px">保存发布记录'+I('check',14)+'</button><div class="note-box">'+I('info',14)+'<span>导出与公开发布分别记录。只有回执核对完成且作品公开展示，才进入公开作品统计。</span></div></div></section></div><div class="studio-footer"><button class="btn ghost" data-action="workflow-step" data-value="review">'+I('arrow-left',13)+'返回审核</button><button class="btn primary" data-action="workflow-step" data-value="learn">查看反馈与复盘'+I('arrow-right',14)+'</button></div>';}
  function learnView(){return '<section class="card"><div class="card-body" style="padding:32px"><div class="row" style="margin-bottom:17px">'+I('chart',22)+'<h2>把内容，带回客户的问题</h2></div><p class="muted" style="font-size:12px;line-height:2;max-width:680px">先记录发布与平台结果，再确认主动咨询与真实需求。复盘建议来自具体的销售反馈，内容负责人采纳后进入下一轮创作。</p><div class="grid-3" style="margin:27px 0"><div class="note-box" style="margin:0">'+I('file',18)+'<span>每个作品有窗口<br><strong>固定 D7 / D30 观察</strong></span></div><div class="note-box" style="margin:0">'+I('users',18)+'<span>每次咨询有负责人<br><strong>人工确认需求与授权</strong></span></div><div class="note-box" style="margin:0">'+I('sparkle',18)+'<span>每条建议有依据<br><strong>采纳后再创作</strong></span></div></div><div class="row"><button class="btn primary" data-action="navigate" data-page="reports">查看效果分析'+I('arrow-right',14)+'</button><button class="btn" data-action="navigate" data-page="leads">查看客户反馈</button></div></div></section>';}
  function render(){const name=ui.page;let body=name==='assistant'?assistantView():name==='dashboard'?dashboard():name==='studio'?studio():name==='property'?V.facts(renderedState()):V[name](renderedState());document.getElementById('app').innerHTML='<div class="app-shell">'+sidebar()+(ui.mobile?'<div class="nav-backdrop" data-action="mobile-menu"></div>':'')+'<div class="main-shell">'+topbar()+'<main class="content '+(name==='assistant'?'assistant-content':'')+'">'+body+'<footer class="subtle-footer"><span>HOUSIGNAL · 把好房讲清楚，把主动咨询接住。</span><span class="demo-caption">虚构楼盘与客户 · 交互演示 v0.4.0</span></footer></main></div></div>';if(name==='leads'){const input=document.getElementById('lead-search');if(input)input.value=ui.search;}const brief=document.getElementById('brief-audience');if(brief&&ui.audience)brief.value=ui.audience;const channel=document.getElementById('brief-channel');if(channel)channel.value=state.campaign.channel==='小红书'?'小红书 · 图文适配':'抖音 · 口播短视频';}
  function openModal(title,body,footer='',options={}){lastFocused=document.activeElement;const drawer=options.drawer;document.getElementById('overlay-root').innerHTML='<div class="overlay '+(drawer?'drawer-overlay':'')+'" data-action="backdrop"><section class="modal '+(drawer?'drawer ':'')+(options.wide?'wide':'')+(options.project?' project-dialog':'')+'" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-header"><h2 id="dialog-title">'+E(title)+'</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭弹窗">'+I('close',18)+'</button></div><div class="modal-body">'+body+'</div>'+(footer?'<div class="modal-footer">'+footer+'</div>':'')+'</section></div>';document.body.style.overflow='hidden';document.getElementById('app').inert=true;document.getElementById('app').setAttribute('aria-hidden','true');const first=document.querySelector('.modal input:not([type=checkbox]),.modal textarea,.modal select')||document.querySelector('.modal input')||document.querySelector('.modal button');if(first)setTimeout(()=>first.focus(),30);}
  function closeModal(){document.getElementById('overlay-root').innerHTML='';document.body.style.overflow='';document.getElementById('app').inert=false;document.getElementById('app').removeAttribute('aria-hidden');if(lastFocused&&document.contains(lastFocused))lastFocused.focus();}
  function footerButtons(primary,action,id='',extra=''){return '<span class="muted" style="font-size:9px">示例交互 · 不提交外部服务</span><div class="row"><button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="'+action+'" '+(id?'data-id="'+E(id)+'"':'')+' '+extra+'>'+primary+'</button></div>';}
  function factModal(id,verifying=false){
    const f=state.facts.find(x=>x.id===id);if(!f)return;
    const status={verified:['已核验','green'],unverified:['待核验','amber'],expired:['已失效','red'],disputed:['有争议','red']};
    let body='<div class="row" style="margin-bottom:20px">'+I('shield',22)+'<h3 style="font-size:18px">'+E(f.label)+'</h3>'+B(...status[f.status])+'</div>';
    if(verifying){body+='<div class="form-grid"><div class="input-group"><label for="fact-value">事实值</label><input id="fact-value" value="'+E(f.value||'')+'" placeholder="按本项目资料填写" maxlength="200"></div><div class="input-group"><label for="fact-unit">单位或口径</label><input id="fact-unit" value="'+E(f.unit||'')+'" placeholder="如：㎡ / 建筑面积" maxlength="40"></div></div><div class="input-group"><label for="fact-source">来源与证据位置</label><textarea id="fact-source" placeholder="如：本项目户型资料第2页，或现场镜头时间码">'+E(f.source||'')+'</textarea></div><label class="checkbox-line"><input id="fact-proof-confirm" type="checkbox"><span>已核对当前项目这项事实的来源、适用范围和表述口径。</span></label>';}
    else{body+='<dl class="detail-grid"><dt>当前记录</dt><dd>'+E(f.value||'待补资料')+' '+E(f.unit)+'</dd><dt>适用项目</dt><dd>'+E(state.property.name)+(state.property.unit?' / '+E(state.property.unit):'')+'</dd><dt>来源位置</dt><dd>'+E(f.source||'待补证据')+'</dd><dt>最近核对</dt><dd>'+E(f.updatedAt)+'</dd><dt>引用状态</dt><dd>'+(f.status==='verified'?'可在当前项目内容中引用':'补齐依据前不进入对外主张')+'</dd></dl>';}
    body+='<div class="note-box">'+I('info',14)+'<span>资料与核验记录只属于 '+E(state.property.name)+'。资料修改后，关联内容需要重新审核。</span></div><div id="fact-error" style="margin-top:15px"></div>';
    const footer=verifying?'<span class="muted" style="font-size:9px">先录入资料，再由人确认</span><div class="row"><button class="btn" data-action="save-fact-draft" data-id="'+E(id)+'">保存为待核验</button><button class="btn primary" data-action="confirm-fact" data-id="'+E(id)+'">确认核验</button></div>':'<span class="muted" style="font-size:9px">事实按项目单独维护</span><div class="row">'+(f.status==='verified'?'<button class="btn ghost small" data-action="expire-fact" data-id="'+E(id)+'">标为失效</button>':'')+'<button class="btn" data-action="verify-fact" data-id="'+E(id)+'">补充或编辑资料</button><button class="btn primary" data-action="close-modal">完成</button></div>';
    openModal(verifying?'完善并核验事实':'查看事实依据',body,footer);
  }
  function inquiryModal(id){const q=state.inquiries.find(x=>x.id===id);if(!q)return;const body='<div class="detail-person">'+A(q.name)+'<div><h3>'+E(q.name)+'</h3><p>'+E(q.channel)+' · '+E(q.lastAt)+' · 主动咨询</p></div></div><dl class="detail-grid"><dt>来源</dt><dd>'+B(sourceLabels[q.sourceConfidence],q.sourceConfidence==='unknown'?'gray':'blue')+'</dd><dt>来源说明</dt><dd>'+E(q.sourceText)+'</dd><dt>咨询问题</dt><dd>'+E(q.need)+'</dd><dt>当前负责人</dt><dd>'+E(q.owner)+'</dd></dl><h3 style="font-size:12px;color:#7286a0;margin-bottom:16px">由销售确认，才能进入资格客户</h3><label class="checkbox-line"><input id="qualify-contact" type="checkbox" '+(q.contactable?'checked':'')+'><span>客户可通过合法渠道联系。</span></label><label class="checkbox-line"><input id="qualify-consent" type="checkbox" '+(q.consent?'checked':'')+'><span>客户同意本次咨询服务所需的联系与记录。</span></label><label class="checkbox-line"><input id="qualify-demand" type="checkbox" '+(q.qualified?'checked':'')+'><span>经过沟通，确认有真实置业或看房需求。</span></label><label class="checkbox-line"><input id="qualify-fit" type="checkbox" '+(q.qualified?'checked':'')+'><span>需求匹配本楼盘，或已明确后续跟进理由。</span></label><div class="input-group" style="margin-top:19px"><label for="inquiry-need">客户主动表达的需求</label><textarea id="inquiry-need">'+E(q.need)+'</textarea></div><div id="inquiry-error"></div>';openModal('咨询详情与需求确认',body,q.qualified?'<span class="muted" style="font-size:10px">此咨询已进入资格客户</span><button class="btn primary" data-action="open-lead" data-id="'+E(state.leads.find(l=>l.inquiryId===q.id)?.id||'')+'">查看客户详情</button>':footerButtons('确认并建立资格客户','confirm-inquiry',id),{drawer:true});}
  function leadModal(id){const l=state.leads.find(x=>x.id===id);if(!l)return;const q=state.inquiries.find(x=>x.id===l.inquiryId),stagesOrder=['qualified','appointment','visit_completed','opportunity','won'];const terminal=['withdrawn','lost','won'].includes(l.stage);const next=stagesOrder[stagesOrder.indexOf(l.stage)+1];const nextLabel={appointment:'记录已预约',visit_completed:'确认已完成带看',opportunity:'进入方案沟通',won:'记录成交结果'};const notes=l.notes.slice().reverse();let body='<div class="detail-person">'+A(l.name)+'<div><h3>'+E(l.name)+'</h3><p>'+B(stages[l.stage],l.stage==='withdrawn'?'gray':'blue')+'</p></div></div><dl class="detail-grid"><dt>需求摘要</dt><dd>'+E(l.need)+'</dd><dt>来源</dt><dd>'+B(sourceLabels[l.sourceConfidence],l.sourceConfidence==='unknown'?'gray':'green')+'</dd><dt>负责顾问</dt><dd>'+E(l.owner)+'</dd><dt>联系范围</dt><dd>'+((q&&q.consent)?'当前咨询服务 · 原已授权渠道':'已停止相应用途的联系')+'</dd><dt>下一步</dt><dd>'+E(l.nextAction)+'</dd></dl><div class="section-title"><h3>跟进记录</h3>'+B(notes.length+' 条反馈','gray')+'</div><div>'+notes.map(n=>'<div class="timeline-item"><h4>'+E(n.by)+' · 沟通反馈</h4><p>'+E(n.text)+'</p><small>刚刚 · 示例记录</small></div>').join('')+'<div class="timeline-item"><h4>销售人工确认需求</h4><p>'+E(l.need)+'</p><small>'+E(l.lastAt)+'</small></div></div>'+(!terminal?'<div class="input-group"><label for="followup-note">本次沟通反馈</label><textarea id="followup-note" placeholder="记录客户实际表达的问题、取舍与下一步。"></textarea></div><div class="input-group"><label for="followup-next">下次行动</label><input id="followup-next" value="'+E(l.nextAction)+'"></div><button class="btn" data-action="save-followup" data-id="'+E(id)+'" style="width:100%">保存跟进'+I('check',13)+'</button>':'<div class="info-strip">'+I('lock',15)+'当前业务已结束，保留历史记录。</div>')+'<div id="lead-error" style="margin-top:15px"></div>';let foot=terminal?'<span class="muted" style="font-size:10px">历史阶段与来源保留</span><button class="btn primary" data-action="close-modal">完成</button>':'<button class="btn ghost small" data-action="withdraw-lead" data-id="'+E(id)+'">停止联系</button><button class="btn primary" data-action="move-lead" data-id="'+E(id)+'" data-stage="'+E(next)+'">'+nextLabel[next]+I('arrow-right',13)+'</button>';openModal('客户详情',body,foot,{drawer:true});}
  function newInquiry(){openModal('录入主动咨询','<p class="modal-text">只记录客户主动提供的必要信息。来源未确认时保留未知。</p><div class="input-group"><label for="new-inquiry-name">称呼</label><input id="new-inquiry-name" placeholder="如：王女士（示例）" maxlength="40"></div><div class="form-grid"><div class="input-group"><label for="new-inquiry-channel">咨询渠道</label><select id="new-inquiry-channel"><option '+(state.campaign.channel==='抖音'?'selected':'')+'>抖音</option><option '+(state.campaign.channel==='小红书'?'selected':'')+'>小红书</option><option>其他</option></select></div><div class="input-group"><label for="new-inquiry-source">来源可信度</label><select id="new-inquiry-source"><option value="unknown">来源未知</option><option value="self_reported">客户自述</option></select></div></div><div class="input-group"><label for="new-inquiry-need">主动提出的问题</label><textarea id="new-inquiry-need" placeholder="如：希望了解家中有长辈时的动线安排。"></textarea></div><div id="new-inquiry-error"></div>',footerButtons('保存咨询候选','save-new-inquiry'));}
  function tour(){openModal('一条内容，连接完整的下一步','<div class="eyebrow">WELCOME TO HOUSIGNAL</div><h3 style="font-size:23px;line-height:1.7;letter-spacing:-.5px;margin-top:12px">把好房讲清楚，<br>把主动咨询接住。</h3><div class="tour-steps">'+[['准备资料','核对楼盘事实与素材，给专业表达一个可信起点。'],['推进创作','选定问题，编辑文案，组织分镜，确认发布版本。'],['接住客户','人工登记回执与咨询，由销售确认真实需求和下一步。'],['让内容进步','从销售反馈中采纳建议，回到下一轮选题。']].map(([title,copy],i)=>'<div class="tour-item"><span class="tour-index">0'+(i+1)+'</span><div><h3>'+title+'</h3><p>'+copy+'</p></div></div>').join('')+'</div><p class="modal-text" style="margin-bottom:0">当前为本地交互演示：虚构楼盘、脱敏客户与示例指标。生成、审核与回执仅演示操作流程。</p>','<span class="muted" style="font-size:9px">修改保存在当前浏览器，可随时重置</span><button class="btn primary" data-action="start-tour">开始体验'+I('arrow-right',14)+'</button>');}
  function command(){openModal('搜索工作区','<div class="search-field" style="width:100%;margin-bottom:17px"><span>'+I('search',16)+'</span><input id="command-input" placeholder="搜索页面、资料或客户" aria-label="搜索页面、资料或客户"></div><div id="command-results" class="command-list" style="padding:0">'+commandResults('')+'</div><div class="command-footer">选择结果前往 · Esc 关闭</div>','',{wide:false});}
  function commandResults(query){const items=[...Object.entries(titles).map(([page,name])=>({name,page,icon:page==='studio'?'studio':page==='leads'?'users':'file'})),...state.leads.map(l=>({name:l.name+' · '+l.need,id:l.id,action:'open-lead',icon:'user'}))];const list=items.filter(x=>x.name.toLowerCase().includes(query.toLowerCase()));return list.length?list.map(x=>'<button data-action="'+(x.action||'navigate')+'" '+(x.page?'data-page="'+x.page+'"':'data-id="'+x.id+'"')+'>'+I(x.icon,17)+E(x.name)+I('arrow-right',13)+'</button>').join(''):'<div class="empty-state" style="padding:18px">没有匹配结果，试试“客户”或“文案”。</div>';}
  function stopPreview(){clearInterval(previewTimer);ui.previewPlaying=false;}
  function playPreview(){ui.previewPlaying=!ui.previewPlaying;clearInterval(previewTimer);render();if(ui.previewPlaying)previewTimer=setInterval(()=>{ui.previewTime=(ui.previewTime+1)%76;const time=document.getElementById('preview-time'),range=document.getElementById('preview-range'),image=document.getElementById('scene-photo'),sub=document.getElementById('preview-subtitle');if(!time){stopPreview();return;}time.textContent=ui.previewTime<60?'00:'+String(ui.previewTime).padStart(2,'0'):'01:'+String(ui.previewTime-60).padStart(2,'0');range.value=ui.previewTime;const idx=Math.min(2,Math.floor(ui.previewTime/25));image.src=photo([3,1,2][idx]);sub.textContent=['家的尺度，从生活开始。','把空间的细节，讲给对的人。','适合与否，让真实需求来回答。'][idx];},1000);}
  function saveCurrentScript(){const editor=document.getElementById('script-editor');if(editor&&editor.value!==state.campaign.script)return act({type:'UPDATE_SCRIPT',text:editor.value},{render:false});return true;}
  function download(text,name,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function busy(button,done){const projectId=workspace.activeProjectId;if(!button)return done(projectId);const original=button.innerHTML;button.innerHTML='<span class="loading-spinner"></span>正在整理';button.disabled=true;setTimeout(()=>{button.innerHTML=original;button.disabled=false;done(projectId);},650);}

  function resetProjectUI(page='dashboard'){stopPreview();ui.page=page;ui.workspaceTab='overview';ui.step=state.campaign.script?'script':'topics';ui.factFilter='all';ui.assetFilter='all';ui.leadView='table';ui.reportWindow='D7';ui.search='';ui.allTopics=false;ui.channel=state.campaign.channel;ui.mobile=false;ui.previewTime=0;ui.audience=state.property.audience||'';}
  function useWorkspace(result,options={}){if(result.error){const target=options.errorTarget&&document.getElementById(options.errorTarget);if(target)target.innerHTML='<div class="modal-error">'+E(result.error)+'</div>';else toast(result.error,true);return false;}workspace=result.workspace;normalizeAssets();save();if(options.switching)resetProjectUI(ui.page==='assistant'?'assistant':'dashboard');if(options.close)closeModal();render();if(result.message)toast(result.message);return true;}
  function projectRows(query=''){
    const needle=query.trim().toLowerCase();const list=workspace.projects.filter(p=>[p.state.property.name,p.state.property.city,p.state.property.propertyType].join(' ').toLowerCase().includes(needle));
    return list.length?list.map(project=>{const p=project.state.property,c=P.getCompleteness(project),active=project.id===workspace.activeProjectId;return '<button class="project-choice '+(active?'selected':'')+'" data-action="switch-project" data-project-id="'+E(project.id)+'" aria-label="切换到 '+E(p.name)+'"><span class="project-choice-icon">'+I('building',23)+'</span><span class="project-choice-copy"><strong>'+E(p.name)+'</strong><small>'+E(p.city||'城市待补')+' · '+E(p.propertyType||'类型待补')+'</small><span class="project-choice-progress"><i style="width:'+c.percent+'%"></i></span></span><span class="project-choice-meta">'+(active?B('当前项目','blue'):B('可切换','gray'))+'<small>资料 '+c.completed+'/'+c.total+' · '+c.percent+'%</small></span>'+I(active?'check':'arrow-right',15)+'</button>';}).join(''):'<div class="empty-state" style="padding:24px">没有匹配项目，可新建一个项目。</div>';
  }
  function projectSelector(){openModal('切换当前项目','<p class="modal-text">资料、素材、内容和销售反馈按项目独立保存。切换后可以随时回来继续。</p><div class="search-field" style="width:100%;margin-bottom:17px">'+I('search',15)+'<input id="project-search" placeholder="搜索项目名称或城市" aria-label="搜索项目名称或城市"></div><div id="project-list" class="project-list">'+projectRows()+'</div>','<button class="btn" data-action="project-completeness">'+I('shield',14)+'项目资料完整度</button><button class="btn primary" data-action="new-project">'+I('plus',14)+'新建项目</button>',{wide:true,project:true});}
  function projectForm(creating=false){const p=creating?{name:'',city:'',propertyType:'大平层',owner:'林嘉宁',audience:'',salesOwner:'',marketingPermission:{confirmed:false,evidence:''}}:state.property;const channel=creating?'抖音':state.campaign.channel;
    const field=(id,label,value,placeholder='',required=false)=>'<div class="input-group"><label for="'+id+'">'+label+(required?' <span class="required-mark">*</span>':'')+'</label><input id="'+id+'" value="'+E(value||'')+'" placeholder="'+E(placeholder)+'" maxlength="120"></div>';
    const body='<div class="eyebrow">'+(creating?'NEW PROPERTY PROJECT':'PROJECT DETAILS')+'</div><p class="modal-text" style="margin-top:10px">'+(creating?'为另一处豪宅建立独立内容工作空间。新项目不会复制已有楼盘的事实、素材、客户或审批。':'补充当前项目资料，相关变更会提示重新审核。')+'</p><div class="form-grid">'+field('project-name','项目名称',p.name,'例如：澜庭·江岸',true)+field('project-city','所在城市',p.city,'例如：杭州',true)+'<div class="input-group"><label for="project-type">物业类型</label><select id="project-type">'+Array.from(new Set([p.propertyType||'大平层','大平层','别墅','洋房','低密庭院住宅','其他'])).map(type=>'<option '+(type===p.propertyType?'selected':'')+'>'+E(type)+'</option>').join('')+'</select></div>'+field('project-owner','资料与内容负责人',p.owner,'例如：林嘉宁')+'</div><div class="project-form-divider"><span>内容与承接 · 可稍后补充</span></div><div class="form-grid">'+field('project-audience','目标生活需求',p.audience,'例如：家庭改善、庭院生活')+'<div class="input-group"><label for="project-channel">主运营渠道</label><select id="project-channel"><option '+(channel==='抖音'?'selected':'')+'>抖音</option><option '+(channel==='小红书'?'selected':'')+'>小红书</option></select></div>'+field('project-sales-owner','销售承接人',p.salesOwner,'例如：林顾问')+'<div class="input-group"><label for="project-entry">咨询承接方式</label><select id="project-entry"><option value="manual_native">平台内人工咨询</option></select></div></div><div class="project-form-divider"><span>营销范围 · 不自动获得平台权限</span></div><label class="checkbox-line"><input id="project-marketing" type="checkbox" '+(p.marketingPermission?.confirmed?'checked':'')+'><span>已确认本项目允许推广的房源范围与用途。</span></label><div class="input-group"><label for="project-marketing-evidence">范围依据与证据位置</label><textarea id="project-marketing-evidence" placeholder="填写对应的范围说明或资料位置；未确认时保持为空">'+E(p.marketingPermission?.evidence||'')+'</textarea></div><div id="project-form-error"></div>';
    openModal(creating?'新建豪宅项目':'完善项目资料',body,footerButtons(creating?'创建独立项目':'保存项目资料',creating?'create-project':'save-project-details'),{wide:true,project:true});
  }
  function readProjectForm(){return {name:document.getElementById('project-name').value,city:document.getElementById('project-city').value,propertyType:document.getElementById('project-type').value,owner:document.getElementById('project-owner').value,audience:document.getElementById('project-audience').value,channel:document.getElementById('project-channel').value,salesOwner:document.getElementById('project-sales-owner').value,entryMode:'manual_native',marketingConfirmed:document.getElementById('project-marketing').checked,marketingEvidence:document.getElementById('project-marketing-evidence').value};}
  function projectCompleteness(){const c=P.getCompleteness(state);openModal('项目资料完整度','<div class="completeness-summary"><div class="completion-ring" style="--progress:'+c.percent+'"><span>'+c.percent+'<small>%</small></span></div><div><h3>'+E(state.property.name)+'</h3><p>已完成 <strong>'+c.completed+' / '+c.total+'</strong> 项资料准备</p><small>准备度按清单计算，不替代事实核验或平台权限确认。</small></div></div><div class="completion-list">'+c.items.map(item=>'<div class="completion-row"><span class="completion-state '+(item.complete?'done':'pending')+'">'+I(item.complete?'check':'clock',13)+'</span><div><strong>'+E(item.label)+'</strong><p>'+E(item.detail)+'</p></div><button class="btn '+(item.complete?'ghost':'soft')+' small" data-action="'+E(item.action)+'">'+(item.complete?'查看':'去完善')+I('arrow-right',12)+'</button></div>').join('')+'</div>','<button class="btn" data-action="project-selector">'+I('building',14)+'切换项目</button><button class="btn primary" data-action="edit-project-details">完善项目资料'+I('arrow-right',13)+'</button>',{wide:true,project:true});}
  function saveFactDraft(id){return act({type:'UPDATE_FACT',id,value:document.getElementById('fact-value').value,unit:document.getElementById('fact-unit').value,source:document.getElementById('fact-source').value},{render:false,toast:false,errorTarget:'fact-error'});}
  function assistantView(){const thread=S.getThread(chats,workspace.activeProjectId);return W.render(state,{projectId:workspace.activeProjectId,projectName:state.property.name,completeness:P.getCompleteness(state),messages:thread.messages,draft:thread.draft,pending:!!thread.pending});}
  function scrollAgent(){const messages=document.getElementById('agent-messages');if(messages)messages.scrollTop=messages.scrollHeight;}
  function sendAgentQuestion(question){
    const projectId=workspace.activeProjectId,epoch=chatEpoch;
    const text=question===undefined?(document.getElementById('agent-input')?.value||''):question;
    const result=S.startQuestion(chats,projectId,text,new Date().toISOString());
    if(result.error){toast(result.error,true);return;}
    chats=result.store;saveChats();render();scrollAgent();
    setTimeout(()=>{
      if(epoch!==chatEpoch)return;
      const thread=S.getThread(chats,projectId);
      if(!thread.pending||thread.pending.id!==result.requestId)return;
      let answer;
      try{answer=L.answer(workspace,projectId,text,thread.messages);}catch(_){answer={projectId,projectName:P.getProject(workspace,projectId)?.state.property.name||'原项目',intent:'error',title:'这次查询没有完成',summary:'请重新提问，或打开对应页面核对当前项目记录。',sections:[],sources:[],suggestions:[]};}
      const finished=S.finishQuestion(chats,projectId,result.requestId,answer,new Date().toISOString());
      chats=finished.store;saveChats();
      if(finished.accepted&&projectId===workspace.activeProjectId&&ui.page==='assistant'){render();scrollAgent();document.getElementById('agent-input')?.focus();}
    },550);
  }
  function openAgentSource(node){
    if(node.dataset.projectId!==workspace.activeProjectId){toast('这条回答属于其他项目，请先切换到对应项目。',true);return;}
    const kind=node.dataset.refKind,id=node.dataset.id;
    if(kind==='completeness'){projectCompleteness();return;}
    if(kind==='page'){if(['property','assets','leads','reports','studio','settings','dashboard'].includes(node.dataset.page))goto(node.dataset.page);return;}
    const map={fact:['facts','property','show-fact'],asset:['assets','assets','show-asset'],lead:['leads','leads','open-lead'],inquiry:['inquiries','leads','open-inquiry'],publication:['publications','reports','show-publication']};
    const entry=map[kind];
    if(!entry||!state[entry[0]].some(record=>record.id===id)){toast('这条记录已更新或不在当前项目中，请重新查询。',true);return;}
    goto(entry[1]);handleAction(entry[2],node);
  }
  function handleAction(action,node){const id=node.dataset.id,value=node.dataset.value;switch(action){
    case 'navigate':if(node.dataset.page==='reports'&&['D7','D30'].includes(node.dataset.window))ui.reportWindow=node.dataset.window;goto(node.dataset.page);break;
    case 'workspace-tab':if(['overview','effects'].includes(value)){ui.page='dashboard';ui.workspaceTab=value;ui.mobile=false;closeModal();render();window.scrollTo({top:0,behavior:'instant'});}break;
    case 'agent-send':sendAgentQuestion();break;
    case 'agent-prompt':sendAgentQuestion(node.dataset.question);break;
    case 'agent-refresh':sendAgentQuestion('请完整汇总当前项目情况，并列出缺项、关键客户和下一步。');break;
    case 'agent-source':openAgentSource(node);break;
    case 'agent-new-chat':openModal('开始新的项目对话','<p class="modal-text">将清空当前项目的演示对话与输入草稿，项目资料和客户记录保留。其他项目的对话不受影响。</p>',footerButtons('开始新对话','agent-confirm-new-chat'));break;
    case 'agent-confirm-new-chat':chats=S.newChat(chats,workspace.activeProjectId);saveChats();closeModal();render();break;
    case 'mobile-menu':ui.mobile=!ui.mobile;render();break;
    case 'workflow-step':if(ui.step==='script'&&!saveCurrentScript())return;stopPreview();ui.step=value;render();window.scrollTo({top:0,behavior:'instant'});break;
    case 'new-content':ui.step='topics';goto('studio');break;
    case 'continue-content':goto('studio',state.campaign.script?'script':'topics');break;
    case 'select-topic':act({type:'SELECT_TOPIC',id},{toast:false});break;
    case 'generate-script':if(!state.campaign.topicId){toast('先选一个主选题，再生成文案。',true);break;}busy(node,projectId=>{if(act({type:'GENERATE_SCRIPT'},{render:false,projectId})){if(projectId===workspace.activeProjectId)ui.step='script';render();window.scrollTo({top:0,behavior:'instant'});}});break;
    case 'refresh-topics':busy(node,()=>toast('5 个示例选题已按现有资料整理，可选择并编辑。'));break;
    case 'all-topics':ui.allTopics=!ui.allTopics;render();break;
    case 'save-script':if(saveCurrentScript()){render();toast('当前文案已保存。');}break;
    case 'to-visual':if(saveCurrentScript()){ui.step='visual';render();window.scrollTo({top:0,behavior:'instant'});}break;
    case 'copy-script':if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(document.getElementById('script-editor')?.value||state.campaign.script).then(()=>toast('口播文案已复制。')).catch(()=>toast('浏览器限制复制，请选中文案手动复制。',true));else toast('请选中文案后使用复制快捷键。');break;
    case 'preview-play':playPreview();break;
    case 'render-preview':busy(node,projectId=>act({type:'RENDER_PREVIEW'},{projectId}));break;
    case 'to-review':stopPreview();ui.step='review';render();window.scrollTo({top:0,behavior:'instant'});break;
    case 'approve-release':if(!document.getElementById('review-confirm')?.checked){toast('请先勾选人工核对确认。',true);break;}if(act({type:'APPROVE_RELEASE',reviewNote:document.getElementById('review-note').value}))toast('示例版本已批准，下一步导出并人工发布。');break;
    case 'export-release':if(act({type:'EXPORT_RELEASE'})){const c=state.campaign,payload={demo:true,notice:'本地示例文案与分镜清单，不含MP4，不证明真实发布。',project:state.property.name,topic:selectedTopic().title,script:c.script,version:c.scriptVersion,channel:c.channel,coverTitle:c.coverTitle,release:c.release,files:['脚本文案','分镜说明','审批清单']};download(JSON.stringify(payload,null,2),'楼响_示例发布包_v'+c.scriptVersion+'.json','application/json;charset=utf-8');}break;
    case 'record-publication':{const raw=document.getElementById('publication-url').value.trim(),pubState=document.getElementById('publication-platform-state').value;const payload={type:'RECORD_PUBLICATION',platformState:pubState};if(/^https?:/i.test(raw))payload.url=raw;else payload.postId=raw;act(payload,{errorTarget:'publication-error'});break;}
    case 'publish-channel':if(act({type:'UPDATE_PACKAGING',channel:value},{render:false})){ui.channel=value;render();}break;
    case 'fact-filter':ui.factFilter=value;render();break;
    case 'assets-filter':ui.assetFilter=value;render();break;
    case 'lead-view':ui.leadView=value;render();break;
    case 'report-window':ui.reportWindow=value;render();break;
    case 'show-fact':factModal(id);break;
    case 'verify-fact':factModal(id,true);break;
    case 'save-fact-draft':if(saveFactDraft(id)){closeModal();render();toast('资料已保存在当前项目，等待核验。');}break;
    case 'confirm-fact':if(!document.getElementById('fact-proof-confirm').checked){document.getElementById('fact-error').innerHTML='<div class="modal-error">请先确认已核对当前项目依据。</div>';break;}if(saveFactDraft(id)&&act({type:'VERIFY_FACT',id},{errorTarget:'fact-error'})){closeModal();render();}break;
    case 'expire-fact':if(act({type:'EXPIRE_FACT',id})){closeModal();}break;
    case 'open-inquiry':inquiryModal(id);break;
    case 'confirm-inquiry':{const payload={type:'QUALIFY_INQUIRY',id,contactable:document.getElementById('qualify-contact').checked,consent:document.getElementById('qualify-consent').checked,demandConfirmed:document.getElementById('qualify-demand').checked,fitConfirmed:document.getElementById('qualify-fit').checked,need:document.getElementById('inquiry-need').value};if(act(payload,{errorTarget:'inquiry-error'})){closeModal();goto('leads');}break;}
    case 'open-lead':leadModal(id);break;
    case 'move-lead':if(act({type:'MOVE_LEAD',id,stage:node.dataset.stage})){leadModal(id);}break;
    case 'save-followup':{if(act({type:'SAVE_FOLLOWUP',id,note:document.getElementById('followup-note').value,nextAction:document.getElementById('followup-next').value},{errorTarget:'lead-error'}))leadModal(id);break;}
    case 'withdraw-lead':openModal('停止联系并保留历史','<p class="modal-text">确认演示客户已撤回相应联系授权。下一步将停止跟进，保留必要历史，不修改为成交或无需求。</p>',footerButtons('确认停止联系','confirm-withdraw',id));break;
    case 'confirm-withdraw':if(act({type:'MOVE_LEAD',id,stage:'withdrawn'})){closeModal();goto('leads');}break;
    case 'new-inquiry':newInquiry();break;
    case 'save-new-inquiry':{const name=document.getElementById('new-inquiry-name').value.trim(),need=document.getElementById('new-inquiry-need').value.trim();if(!name||!need){document.getElementById('new-inquiry-error').innerHTML='<div class="modal-error">请填写称呼和客户主动提出的问题。</div>';break;}state.inquiries.push({id:'INQ'+Date.now(),name,need,channel:document.getElementById('new-inquiry-channel').value,sourceConfidence:document.getElementById('new-inquiry-source').value,sourceText:'人工登记的示例咨询，具体作品待核对',contactable:false,consent:false,qualified:false,owner:'待分配',lastAt:'刚刚',avatar:name.slice(0,1)});save();closeModal();render();toast('示例咨询已保存，等待销售确认。');break;}
    case 'approve-proposal':act({type:'APPROVE_PROPOSAL',id});break;
    case 'switch-role':ui.role=value;render();toast('已切换为'+({content:'内容编辑',sales:'销售',reviewer:'审核负责人'}[value])+'的演示视角。');break;
    case 'role-menu':openModal('选择演示视角','<div class="command-list">'+[['content','edit','内容负责人'],['reviewer','shield','审核负责人'],['sales','users','销售顾问']].map(([v,i,t])=>'<button data-action="choose-role" data-value="'+v+'">'+I(i,19)+t+I('arrow-right',13)+'</button>').join('')+'</div><p class="modal-text">用于体验不同业务责任，实际权限由组织管理员授予。</p>');break;
    case 'choose-role':ui.role=value;closeModal();render();toast('已切换演示视角。');break;
    case 'entry-settings':openModal('咨询入口配置','<div class="row" style="margin-bottom:20px">'+I('message',25)+'<div><h3>平台内人工咨询</h3><p class="muted" style="font-size:11px">首轮试点默认路径</p></div>'+B('已选用','blue')+'</div><div class="tour-steps">'+[['客户主动咨询','由客户在平台允许的入口发起。'],['销售人工回应','按相应授权范围沟通和记录。'],['最少信息进入 CRM','确认需求，再安排后续服务。']].map(([t,d],i)=>'<div class="tour-item"><span class="tour-index">'+(i+1)+'</span><div><h3>'+t+'</h3><p>'+d+'</p></div></div>').join('')+'</div><div class="note-box">'+I('lock',14)+'<span>官方线索组件与自有表单尚未启用。实际账号能力确认后，才可配置对应入口。</span></div>','<span class="muted" style="font-size:9px">本地演示 · 未连接平台</span><button class="btn primary" data-action="close-modal">了解并保留当前路径</button>');break;
    case 'project-selector':projectSelector();break;
    case 'switch-project':if(node.dataset.projectId===workspace.activeProjectId){closeModal();break;}if(saveCurrentScript()){useWorkspace(P.switchProject(workspace,node.dataset.projectId),{switching:true,close:true});window.scrollTo({top:0,behavior:'instant'});}break;
    case 'new-project':projectForm(true);break;
    case 'create-project':if(saveCurrentScript())useWorkspace(P.createProject(workspace,readProjectForm()),{switching:true,close:true,errorTarget:'project-form-error'});break;
    case 'project-completeness':projectCompleteness();break;
    case 'edit-project-details':projectForm(false);break;
    case 'save-project-details':if(useWorkspace(P.updateProject(workspace,workspace.activeProjectId,readProjectForm()),{close:true,errorTarget:'project-form-error'})){ui.channel=state.campaign.channel;ui.audience=state.property.audience;render();}break;
    case 'project-facts':goto('property');break;
    case 'project-assets':goto('assets');break;
    case 'date-range':openModal('当前演示观察窗口','<div class="input-group"><label>作品与咨询记录</label><input value="2026 年 10 月 01 日 — 10 月 11 日" readonly></div><p class="modal-text">作品指标采用发布后 D7 的独立累计窗口；客户队列按实际示例事件展示，不能把它当作内容因果归因。</p>','<button class="btn primary" data-action="navigate" data-page="reports">查看窗口与指标</button>');break;
    case 'notifications':{const pending=state.inquiries.filter(q=>!q.qualified),missing=P.getCompleteness(state).items.filter(item=>!item.complete);openModal('本项目待办','<div class="command-list">'+(pending.length?'<button data-action="open-inquiry" data-id="'+E(pending[0].id)+'">'+I('users',17)+pending.length+' 条咨询待销售确认'+I('arrow-right',13)+'</button>':'')+missing.map(item=>'<button data-action="'+E(item.action)+'">'+I('shield',17)+E(item.label)+'待完善'+I('arrow-right',13)+'</button>').join('')+'<button data-action="navigate" data-page="reports">'+I('chart',17)+state.proposals.filter(proposal=>proposal.status==='pending').length+' 条复盘建议待采纳'+I('arrow-right',13)+'</button></div>');break;}
    case 'show-publication':{const p=state.publications.find(x=>x.id===id);if(!p)return;openModal('作品与发布记录','<h3 style="font-size:18px;margin-bottom:20px">'+E(p.title)+'</h3><dl class="detail-grid"><dt>渠道</dt><dd>'+E(p.channel)+'</dd><dt>发布日期</dt><dd>'+E(p.at)+'</dd><dt>回执核对</dt><dd>'+B(p.status==='verified'?'已人工核对':'待核对',p.status==='verified'?'green':'amber')+'</dd><dt>D7 播放</dt><dd>'+(p.views==null?'待回填':p.views.toLocaleString('zh-CN'))+'</dd></dl><div class="input-group"><label for="receipt-state">平台实际状态</label><select id="receipt-state">'+Object.entries({live:'公开展示',review_pending:'平台审核中',rejected:'平台拒绝',restricted:'展示受限',removed:'已撤下',unknown:'状态未知'}).map(([value,label])=>'<option value="'+value+'" '+(p.platformState===value?'selected':'')+'>'+label+'</option>').join('')+'</select></div><label class="checkbox-line"><input id="receipt-confirm" type="checkbox"><span>我已人工核对当前示例作品的账号、版本和回执依据。</span></label><div id="receipt-error"></div><p class="modal-text" style="margin-bottom:0">以上为模拟数据；演示只记录人工核对动作，不连接真实平台。</p>',footerButtons('保存核对结果','verify-publication',id));break;}
    case 'verify-publication':if(act({type:'VERIFY_PUBLICATION',id,receiptConfirmed:document.getElementById('receipt-confirm').checked,platformState:document.getElementById('receipt-state').value},{errorTarget:'receipt-error'})){closeModal();render();}break;
    case 'show-asset':{const asset=state.assets.find(x=>x.id===id);if(!asset)return;openModal('素材详情','<img src="'+E(asset.src)+'" alt="素材示意" style="width:100%;height:240px;border-radius:8px;object-fit:cover;margin-bottom:20px"><h3 style="font-size:15px;margin-bottom:15px">'+E(asset.name)+'</h3><dl class="detail-grid"><dt>空间标签</dt><dd>'+E(asset.space)+'</dd><dt>素材用途</dt><dd>虚构楼盘的视觉交互演示</dd><dt>当前状态</dt><dd>'+B(asset.rights==='authorized'?'示例授权可用':'待确认用途',asset.rights==='authorized'?'green':'amber')+'</dd></dl><p class="modal-text">预置素材为摄影示意图，视频卡只展示分镜模板，不代表已有实拍视频。</p>',asset.localUpload&&asset.rights!=='authorized'?footerButtons('确认仅用于本地演示','authorize-asset',id):'<button class="btn primary" data-action="close-modal">完成</button>',{wide:true});break;}
    case 'authorize-asset':{if(act({type:'AUTHORIZE_ASSET',id},{render:false})){closeModal();render();toast('本次本地演示用途已确认；相关内容需重新审核。');}break;}
    case 'upload-assets':document.getElementById('asset-upload').click();break;
    case 'cover-edit':openModal('封面文案','<div class="input-group"><label for="cover-title">封面标题</label><textarea id="cover-title" maxlength="60">'+E(state.campaign.coverTitle||selectedTopic().title)+'</textarea></div><p class="modal-text">标题调整会改变发布包装，需要重新核对审核版本。</p>',footerButtons('保存封面文字','save-cover'));break;
    case 'save-cover':{const value=document.getElementById('cover-title').value.trim();if(!value){toast('请输入封面文字。',true);break;}if(act({type:'UPDATE_PACKAGING',coverTitle:value},{render:false})){closeModal();render();toast('封面文字已保存，原审批失效。');}break;}
    case 'tour':tour();break;
    case 'start-tour':goto('studio','topics');break;
    case 'command':command();break;
    case 'reset-demo':openModal('恢复初始演示','<p class="modal-text">这会清除本地新建项目、对话及各项目的演示改动，恢复两个初始示例项目。原始 PRD 与文档保持原样。</p>',footerButtons('恢复初始演示','confirm-reset'));break;
    case 'confirm-reset':chatEpoch+=1;chats=S.createSession();saveChats();workspace=P.createWorkspace();normalizeAssets();save();resetProjectUI();closeModal();goto('dashboard');toast('已恢复两个初始示例项目。');break;
    case 'close-modal':closeModal();break;
  }}
  document.addEventListener('click',event=>{const node=event.target.closest('[data-action]');if(!node)return;const action=node.dataset.action;if(action==='backdrop'){if(event.target===node)closeModal();return;}event.preventDefault();handleAction(action,node);});
  document.addEventListener('keydown',event=>{if(event.target.id==='agent-input'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing&&event.keyCode!==229){event.preventDefault();sendAgentQuestion();return;}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();command();}if(event.key==='Escape'){closeModal();if(ui.mobile){ui.mobile=false;render();}}const dialog=document.querySelector('.modal');if(dialog&&event.key==='Tab'){const focusables=Array.from(dialog.querySelectorAll('button,input,select,textarea,[tabindex="0"]')).filter(n=>!n.disabled&&n.offsetParent!==null);if(focusables.length){const first=focusables[0],last=focusables[focusables.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-action][role="button"]')){event.preventDefault();handleAction(event.target.dataset.action,event.target);}});
  document.addEventListener('input',event=>{if(event.target.id==='agent-input'){chats=S.setDraft(chats,workspace.activeProjectId,event.target.value);saveChats();const send=document.querySelector('[data-action="agent-send"]');if(send)send.disabled=!event.target.value.trim()||!!S.getThread(chats,workspace.activeProjectId).pending;}if(event.target.id==='project-search'){document.getElementById('project-list').innerHTML=projectRows(event.target.value);}if(event.target.id==='command-input'){document.getElementById('command-results').innerHTML=commandResults(event.target.value);}if(event.target.id==='lead-search'){ui.search=event.target.value;const cursor=event.target.selectionStart;render();const input=document.getElementById('lead-search');input.focus();try{input.setSelectionRange(cursor,cursor);}catch(_){}}if(event.target.id==='preview-range'){ui.previewTime=Number(event.target.value);const idx=Math.min(2,Math.floor(ui.previewTime/25));document.getElementById('scene-photo').src=photo([3,1,2][idx]);const time=document.getElementById('preview-time');time.textContent=ui.previewTime<60?'00:'+String(ui.previewTime).padStart(2,'0'):'01:'+String(ui.previewTime-60).padStart(2,'0');}});
  document.addEventListener('change',event=>{if(event.target.id==='brief-audience'){ui.audience=event.target.value;render();toast('已按当前生活需求调整示例选题顺序。');}if(event.target.id==='brief-channel'){const channel=event.target.value.startsWith('小红书')?'小红书':'抖音';if(act({type:'UPDATE_PACKAGING',channel},{render:false})){ui.channel=channel;render();}}if(event.target.id==='ratio-select'){act({type:'UPDATE_PACKAGING',aspectRatio:event.target.value});}if(event.target.id==='subtitle-style'){act({type:'UPDATE_PACKAGING',subtitleStyle:event.target.value});}if(event.target.id==='asset-upload'){const files=Array.from(event.target.files||[]);if(!files.length)return;for(const file of files){if(!file.type.startsWith('image/')){toast('本演示预览图片素材；视频请在正式制作流程中接入。',true);continue;}if(file.size>8*1024*1024){toast('演示素材请控制在 8MB 以内。',true);continue;}act({type:'ADD_ASSET',asset:{id:'LOCAL'+Date.now()+Math.random().toString(16).slice(2,6),name:file.name,space:'待标记',type:'image',duration:'—',rights:'pending',src:URL.createObjectURL(file),localUpload:true}},{render:false,toast:false});}save();ui.page='assets';render();toast('图片已加入本次预览；用途待确认，刷新后需重新选择。');event.target.value='';}});
  window.HouSignalDemo={getState:()=>JSON.parse(JSON.stringify(state)),getWorkspace:()=>JSON.parse(JSON.stringify(workspace)),getUI:()=>({...ui}),reset:()=>{chatEpoch+=1;chats=S.createSession();saveChats();workspace=P.createWorkspace();normalizeAssets();save();resetProjectUI();goto('dashboard');},navigate:goto};
  render();
})();
